/* Hoops Dynasty contract rules, not a reproduction of the NBA CBA. Amounts in millions. */
let faBusy=false;
function faActive(){return state.freeAgency?.year===state.year&&['resign','market'].includes(state.freeAgency.phase)}
function faMinimum(p){return leagueRules().minContract}
function faEntry(id){return state.freeAgency?.players.find(p=>p.id===id)}
function faPayroll(t){return t.roster.reduce((n,p)=>n+p.salary,0)+(state.finances?.[t.id]?.dead||[]).filter(d=>d.through>=state.year+1).reduce((n,d)=>n+d.salary,0)}
function faDemand(p){return Math.max(faMinimum(p),Math.round(Math.max(1,(p.ovr-55)*.48)*(p.age>32?.85:1)*(hasTrait(p,'mercenary')?1.2:1)*10)/10)}
function faLog(text){state.freeAgency.log.unshift(text);state.freeAgency.log=state.freeAgency.log.slice(0,80)}
async function faSave(before){if(await save()===false){state=before;toast('Could not save free agency. Please try again.');render();return false}render();return true}
async function beginFreeAgency(){if(faBusy||!gmCanAdvance()||!draftComplete()||!draftReady())return;if(wnbaEnabled()&&wnbaTransitionError())return toast(wnbaTransitionError());if(state.freeAgency?.year===state.year)return go('Free agency');faBusy=true;const before=snapshotState();try{
 ownerFinalize();if(!gmCanAdvance())return;archiveStatsSeason();internationalOffseason();offseasonLifecycle();
 const f=state.freeAgency={year:state.year,phase:'resign',round:1,players:[],offers:[],pending:[],mle:{},log:[]};
 for(const t of state.teams){const expired=t.roster.filter(p=>(p.contractThrough??state.year)<=state.year),moods=new Map(expired.map(p=>[p.id,moraleDetails(p,t).score]));t.roster=t.roster.filter(p=>!expired.includes(p));for(const p of expired){if(wnbaEnabled()&&p.wnbaContract){(state.wnbaFinance.contractArchive??=[]).push({id:p.id,team:t.id,closedYear:state.year,contract:copy(p.wnbaContract)});p.wnbaService={seasons:wnbaService(p,state.year+1),asOf:state.year+1,evidence:'recorded_expiration'};delete p.wnbaContract;delete p.contractThrough;}p.previousTeamKey=t.key;state.free.push(p);f.players.push({id:p.id,former:t.id,rfa:wnbaEnabled()?p.wnbaRights?.qualifyingOfferYear===state.year+1&&wnbaRules(state.year+1).rfaService.includes(wnbaService(p,state.year+1)):p.age<=25&&p.bio?.draftTeam===t.abbr,departureMood:moods.get(p.id),demand:faDemand(p)})}}
 if(wnbaEnabled())wnbaCPURights();else cpuSignDraftRights();
 for(const p of state.free)if(!f.players.some(x=>x.id===p.id))f.players.push({id:p.id,former:null,rfa:false,demand:faDemand(p)});
 faLog('Exclusive re-signing window opened for three negotiation rounds.');view='Free agency';await faSave(before);
 }catch(e){state=before;simulationFailure(e);toast(e.message)}finally{faBusy=false;render()}}
function faOfferCheck(p,t,offer,ignorePending=false){if(wnbaEnabled())return wnbaFAOfferCheck(p,t,offer);const f=state.freeAgency,e=faEntry(p.id);if(!faActive()||!e||!state.free.some(x=>x.id===p.id))return 'Player is not available.';if(f.phase==='resign'&&e.former!==t.id)return 'Only the former team can negotiate in this window.';if(!Number.isFinite(offer.salary)||offer.salary<faMinimum(p)||offer.salary>leagueRules().maxContract||!Number.isInteger(offer.years)||offer.years<leagueRules().minContractYears||offer.years>leagueRules().maxContractYears||!Number.isInteger(offer.minutes)||offer.minutes<0||offer.minutes>40)return 'Choose a salary within the league contract limits, '+leagueRules().minContractYears+'–'+leagueRules().maxContractYears+' years, and 0–40 minutes.';
 const held=f.pending.filter(s=>s.offer.team===t.id&&s.id!==p.id),pay=faPayroll(t)+held.reduce((n,s)=>n+s.offer.salary,0),freed=offer.swap!==undefined&&t.roster.some(q=>q.id===offer.swap)&&!held.some(s=>s.offer.swap===offer.swap)?1:0;if(t.roster.length-freed+held.length>=rosterMaximum())return 'No roster spot available.';if(pay+offer.salary>financeRosterLimit(t,state.year+1)+.001)return 'Offer exceeds the league payroll ceiling.';
 if(leagueRules().salaryCapType==='none'&&['cap','bird','mle','minimum'].includes(offer.route))return '';
 if(offer.route==='bird'){if(e.former!==t.id)return 'Bird-style rights belong to the former team only.'}
 else if(offer.route==='mle'){const reserved=held.filter(s=>s.offer.route==='mle').reduce((n,s)=>n+s.offer.salary,0);if((f.mle[t.id]||0)+reserved+offer.salary>salaryCap()*.08+.001)return 'Not enough of the mid-level exception remains.'}
 else if(offer.route==='minimum'){if(Math.abs(offer.salary-faMinimum(p))>.01)return 'Minimum exception must equal the player’s minimum salary.'}
 else if(offer.route==='cap'){if(pay+offer.salary>expansionCap(t,state.year+1)+.001)return 'Insufficient salary-cap room.'}else return 'Choose a valid signing route.';return '';
}
function faRoute(p,t,salary){const e=faEntry(p.id);if(leagueRules().salaryCapType==='none')return 'cap';if(e.former===t.id)return 'bird';if(faPayroll(t)+salary<=expansionCap(t,state.year+1))return 'cap';if(Math.abs(salary-faMinimum(p))<.01)return 'minimum';return 'mle'}
// Interest a player needs to accept. In the open market it drops 2 points a round (floor 35): late free agents take
// the jobs that are left instead of holding out forever, which could stall free agency for a team nobody likes.
// Teams below this share of the cap spend toward market value instead of waiting for prices to fall.
const FA_SPEND_FLOOR=.9;
function faAcceptThreshold(f=state.freeAgency){return f?.phase==='market'?Math.max(35,60-2*Math.max(0,(f.round||1)-1)):60}
function faInterest(p,t,o){const e=faEntry(p.id),cash=Math.min(1.4,o.salary/e.demand),win=(t.w+1)/(t.w+t.l+2),same=t.roster.filter(q=>q.pos===p.pos),realistic=same.length?Math.max(8,36-same.filter(q=>q.ovr>=p.ovr).length*12):36,role=Math.min(o.minutes,realistic)/36,market=hasTrait(p,'diva')?({Small:.3,Medium:.6,Large:1}[t.marketSize]||.6):t.marketSize===['Small','Medium','Large'][p.id%3]?1:.5,facilities=(state.finances?.[t.id]?.level||0)/5,coach=coachingSkill(t,'teaching')/100,loyal=e.former===t.id?1:0;
 const weights=hasTrait(p,'mercenary')?[88,2,2,2,2,2,2]:hasTrait(p,'diva')?[45,10,25,10,3,5,2]:hasTrait(p,'loyal')?[48,12,12,3,5,5,15]:[55,15,15,5,4,6,0];const values=[cash,win,role,market,facilities,coach,loyal];const unhappy=e.former===t.id&&(e.departureMood??65)<40,score=values.reduce((sum,v,i)=>sum+v*weights[i],0)-(unhappy?25:0);return {score,realistic,feedback:unhappy?'Unhappy with the previous situation':cash<.9?'Salary is below demand':o.minutes>realistic?'Crowded rotation limits the promised role':hasTrait(p,'mercenary')?'Prioritizes annual salary':hasTrait(p,'diva')?'Prioritizes a featured role':hasTrait(p,'loyal')&&loyal?'Values staying with the franchise':win<.4?'Concerned about winning prospects':'Competitive offer and team fit'};
}
function faSign(p,o){if(wnbaEnabled())return wnbaFASign(p,o);const f=state.freeAgency,t=state.teams[o.team];const error=faOfferCheck(p,t,o,true);if(error)return false;const swap=o.swap!==undefined&&t.roster.length>=rosterMaximum()?t.roster.find(q=>q.id===o.swap):null;if(swap&&!cpuRelease(t,swap,{text:'to make room for '+p.name,allowBelowMinimum:true}))return false;if(swap){if(!f.players.some(x=>x.id===swap.id))f.players.push({id:swap.id,former:t.id,rfa:false,demand:faDemand(swap)});faLog(`${t.city} released ${swap.name} to make room for ${p.name}.`)}internationalPrepareSigning(p);p.salary=o.salary;p.contractThrough=state.year+o.years;p.rotationMinutes=o.minutes;p.moraleAdjustment=8;p.tradeWait=15;t.roster.push(p);state.free=state.free.filter(q=>q.id!==p.id);if(o.route==='mle')f.mle[t.id]=(f.mle[t.id]||0)+o.salary;f.offers=f.offers.filter(x=>x.id!==p.id);faLog(`${t.city} signed ${p.name}: ${money(o.salary)} / year for ${o.years} seasons (${o.route}).`);say(`${gmLead(t)} signs ${p.name}.`);if(t.id===controlledTeamId())addDecision({type:'Signing',description:'Signed '+p.name+' for '+money(o.salary)+' per year ('+o.years+' seasons).',players:[{id:p.id,name:p.name}],reasoning:'Offseason free-agent agreement',immediateOutcome:{capChange:'-'+o.salary.toFixed(1)+'M'}});return true}
function faCPUOffers(){if(wnbaEnabled())return wnbaCPUOffers();faCPUUpgradeOffers();const f=state.freeAgency;for(const t of state.teams.filter(t=>t.id!==controlledTeamId()||simulationAutopilot())){if(t.roster.length>=Math.min(rosterMaximum(),Math.max(12,rosterMinimum())))continue;const candidates=state.free.filter(p=>!f.pending.some(s=>s.id===p.id)&&(f.phase==='market'||faEntry(p.id)?.former===t.id)).sort((a,b)=>{const score=p=>p.ovr+(p.pot-p.ovr)*.25-t.roster.filter(q=>q.pos===p.pos).length*5-(faEntry(p.id)?.demand??faDemand(p));return score(b)-score(a)||a.id-b.id});let budget=financeRosterLimit(t,state.year+1)-faPayroll(t),spots=rosterMaximum()-t.roster.length;const underFloor=faPayroll(t)<salaryCap()*FA_SPEND_FLOOR;for(const p of candidates){if(spots<=0||f.offers.filter(o=>o.team===t.id).length>=3)break;const e=faEntry(p.id),salary=roundContractAmount(Math.max(faMinimum(p),Math.min(leagueRules().maxContract,(underFloor?Math.max(e.demand,Math.min(e.ask??e.demand,budget)):e.demand)*(hasTrait(p,'mercenary')?1.06:1.02)))),o={id:p.id,team:t.id,salary,years:contractTerm(p.age>31?1:p.age<25?3:2),minutes:t.roster.filter(q=>q.ovr>=p.ovr).length<5?32:18,route:faRoute(p,t,salary)};if(salary>budget||faOfferCheck(p,t,o))continue;f.offers.push(o);budget-=salary;spots--}}}
async function advanceFreeAgency(){if(faBusy||!faActive()||!gmCanAdvance())return;if(state.freeAgency.pending.some(s=>s.former===controlledTeamId()))return toast('Resolve your restricted free-agent offer sheets first.');faBusy=true;const before=snapshotState();try{const f=state.freeAgency;gmResolveAISheets();faCPUOffers();
 for(const p of [...state.free]){if(f.pending.some(s=>s.id===p.id))continue;const e=faEntry(p.id);if(!e)continue;const offers=f.offers.filter(o=>o.id===p.id).filter(o=>!faOfferCheck(p,state.teams[o.team],o)).map(o=>({o,interest:faInterest(p,state.teams[o.team],o)})).sort((a,b)=>b.interest.score-a.interest.score||b.o.salary-a.o.salary||a.o.team-b.o.team),best=offers[0];
 if(best&&best.o.salary>=e.demand*.85&&best.interest.score>=faAcceptThreshold()){if(e.rfa&&e.former!==best.o.team){const match={...best.o,team:e.former,route:wnbaEnabled()?'cap':'bird'};if(e.former===controlledTeamId()&&!simulationAutopilot()){f.pending.push({id:p.id,former:controlledTeamId(),offer:best.o});faLog(`${p.name} received an offer sheet from ${state.teams[best.o.team].city}. Match or decline before advancing.`)}else{const former=state.teams[e.former],willMatch=former.roster.length<Math.min(rosterMaximum(),Math.max(12,rosterMinimum()))&&p.ovr>=68&&!faOfferCheck(p,former,match,true);faSign(p,willMatch?match:best.o)}}else faSign(p,best.o)}else if(f.offers.some(o=>o.id===p.id&&o.team===controlledTeamId())){faLog(`${p.name} declined: ${best?best.interest.feedback:'offer no longer fits cap or roster limits'}.`)}
 // Unanswered demand falls 4% a round but not below 60% of the opening ask, so free agency doesn't sell players far
 // below their market value (it pulled league payroll from ~$142M to ~$110M under a $150M cap).
 if(state.free.some(x=>x.id===p.id)&&!f.pending.some(s=>s.id===p.id)){e.ask??=e.demand;e.demand=roundContractAmount(Math.max(faMinimum(p),e.ask*.6,Math.min(wnbaEnabled()?wnbaMillions(wnbaMaximum(p,team(),state.year+1)):leagueRules().maxContract,e.demand*(offers.length>1?1.04:.96))));}
 }
 f.offers=[];f.round++;if(f.phase==='resign'&&f.round>3){f.phase='market';f.round=1;faLog('Open market: all teams may now submit offers.')}await faSave(before);
 }catch(e){state=before;simulationFailure(e);toast(e.message)}finally{faBusy=false;render()}}
async function matchFreeAgent(id,match){if(faBusy||!ownerCanManage())return;const f=state.freeAgency,s=f?.pending.find(s=>s.id===id&&s.former===controlledTeamId()),p=state.free.find(p=>p.id===id);if(!s||!p)return;const before=snapshotState(),o=match?{...s.offer,team:controlledTeamId(),route:wnbaEnabled()?'cap':'bird'}:s.offer,error=faOfferCheck(p,state.teams[o.team],o,true);if(error)return toast(error);faBusy=true;f.pending=f.pending.filter(x=>x!==s);faSign(p,o);await faSave(before);faBusy=false;render()}
function faOfferDialog(id){const p=state.free.find(p=>p.id===id),e=faEntry(id);if(!p||!e||!faActive())return;if(state.freeAgency.pending.some(s=>s.id===id))return toast('This player has a pending offer sheet.');const existing=state.freeAgency.offers.find(o=>o.id===id&&o.team===controlledTeamId()),o=existing||{salary:e.demand,years:contractTerm(2),minutes:24,route:faRoute(p,team(),e.demand)};titleModal('Negotiate with '+escapeHTML(p.name),`<p>Demand: ${money(e.demand)} / year · Minimum: ${money(faMinimum(p))} · ${e.rfa?'Restricted free agent':'Unrestricted free agent'}</p><form onsubmit="submitFreeAgentOffer(event,${id})"><div class="tm-grid"><label>Annual salary ($M)<input name="salary" type="number" min="${faMinimum(p)}" max="${leagueRules().maxContract}" step="${contractMoneyStep()}" value="${o.salary}" required></label><label>Seasons<select name="years">${contractTerms().map(y=>`<option ${o.years===y?'selected':''}>${y}</option>`).join('')}</select></label><label>Promised minutes<input name="minutes" type="number" min="0" max="40" value="${o.minutes}" required></label><label>Signing route<select name="route">${[['cap','Cap room'],['bird','Bird-style re-signing'],['mle','Mid-level exception'],['minimum','Veteran minimum']].map(([k,n])=>`<option value="${k}" ${o.route===k?'selected':''}>${n}</option>`).join('')}</select></label></div><p>Offers are evaluated together when you advance the round. Promised minutes become the player’s target; rotation competition affects interest.</p><p id="fa-offer-error" role="alert"></p><button class="primary">Submit offer</button></form>`)}
async function submitFreeAgentOffer(event,id){event.preventDefault();if(faBusy||!ownerCanManage())return;const v=Object.fromEntries(new FormData(event.target)),p=state.free.find(p=>p.id===id),o={id,team:controlledTeamId(),salary:Number(v.salary),years:Number(v.years),minutes:Number(v.minutes),route:v.route},error=p?faOfferCheck(p,team(),o):'Player is unavailable.';if(error){document.getElementById('fa-offer-error').textContent=error;return}const before=snapshotState();faBusy=true;state.freeAgency.offers=state.freeAgency.offers.filter(x=>x.id!==id||x.team!==controlledTeamId());state.freeAgency.offers.push(o);if(await faSave(before)){closeTitleModal();toast('Offer submitted. '+faInterest(p,team(),o).feedback)}faBusy=false;render()}
async function withdrawFreeAgentOffer(id){if(faBusy)return;const before=snapshotState();state.freeAgency.offers=state.freeAgency.offers.filter(o=>o.id!==id||o.team!==controlledTeamId());await faSave(before)}
async function finishFreeAgency(){if(faBusy||!faActive()||state.freeAgency.phase!=='market'||!gmCanAdvance())return;if(state.freeAgency.pending.length)return toast('Resolve all offer sheets first.');if(state.teams.some(t=>t.roster.length<(wnbaEnabled()?wnbaRules(state.year+1).rosterMin:rosterMinimum())))return toast('Every team needs at least '+(wnbaEnabled()?wnbaRules(state.year+1).rosterMin:rosterMinimum())+' players. Continue bidding rounds.');if(state.teams.some(t=>wnbaEnabled()?wnbaLedger(t,state.year+1).total>wnbaRules(state.year+1).cap:faPayroll(t)>financeRosterLimit(t,state.year+1)+.001))return toast('A team exceeds the hard spending ceiling.');const before=snapshotState();faBusy=true;state.freeAgency.phase='complete';state.freeAgency.offers=[];if(await faSave(before))toast('Free agency complete. You can start the next season.');faBusy=false;render()}
const faNewSeasonBefore=newSeason;newSeason=function(){if(!draftComplete())return faNewSeasonBefore();if(state.freeAgency?.year!==state.year||state.freeAgency.phase!=='complete'){go('Free agency');return}for(const t of state.teams){t.roster.sort((a,b)=>b.ovr-a.ovr);delete t.rotationPlan}return faNewSeasonBefore()};
const faPhaseBefore=seasonPhaseLabel;seasonPhaseLabel=function(){return faActive()?state.freeAgency.phase==='resign'?'Re-signing':'Free Agency':faPhaseBefore()};
const faSignBefore=sign;sign=function(id){if(faActive())return faOfferDialog(id);const p=state.free.find(p=>p.id===id);if(p&&payroll()+freeAgentQuote(p)>financeCapRoomLimit())return toast('Not enough salary-cap room. Offseason exceptions are available in Free Agency.');return faSignBefore(id)};
function freeAgencyView(){if(!faActive()){const ready=draftComplete(),done=state.freeAgency?.year===state.year&&state.freeAgency.phase==='complete';return `<section class="panel"><div class="panelhead"><h2>Free agency</h2></div><div class="award-body"><p>${done?'Negotiations are complete. Your roster is ready for next season.':ready?'The draft is complete. Start the exclusive re-signing period for expiring contracts.':'Offseason bidding opens after the playoffs, lottery and draft. In-season signings use available cap room.'}</p>${ready?`<button class="primary" onclick="${done?'newSeason()':'beginFreeAgency()'}">${done?'Start next season':'Begin re-signing period'}</button>`:''}</div></section>${ready?'':faMarketTable(state.free)}`}
 const f=state.freeAgency,available=state.free.filter(p=>faEntry(p.id)&&(f.phase==='market'||faEntry(p.id).former===controlledTeamId())),held=f.pending.filter(s=>s.former===controlledTeamId());return `<div class="fa-page"><section class="panel"><div class="panelhead"><div><h2>${f.phase==='resign'?'Exclusive re-signing':'Open market'} · Round ${f.round}</h2><small>Negotiating contracts for ${seasonLabel(state.year+1)}</small></div><button class="primary" onclick="advanceFreeAgency()" ${faBusy||held.length?'disabled':''}>Advance negotiation round</button></div><div class="award-body"><div class="po-summary"><div><small>NEXT-SEASON PAYROLL</small><strong>${money(faPayroll(team()))}</strong></div><div><small>CAP ROOM</small><strong>${money(Math.max(0,salaryCap()-faPayroll(team())))}</strong></div><div><small>MLE REMAINING</small><strong>${money(Math.max(0,salaryCap()*.08-(f.mle[controlledTeamId()]||0)))}</strong></div><div><small>ROSTER</small><strong>${team().roster.length} / ${rosterMaximum()}</strong></div></div>${held.map(s=>{const p=state.free.find(p=>p.id===s.id);return `<div class="award-spotlight"><div><h3>Match ${escapeHTML(p.name)}?</h3><p>${escapeHTML(state.teams[s.offer.team].city)} offered ${money(s.offer.salary)} per year for ${s.offer.years} years.</p><button class="primary" onclick="matchFreeAgent(${p.id},true)">Match offer</button> <button onclick="matchFreeAgent(${p.id},false)">Decline matching rights</button></div></div>`}).join('')}<p>${f.phase==='resign'?'Your expiring players are available exclusively for three rounds. CPU teams negotiate with their own players simultaneously.':'Competing offers are private until the round resolves. Players consider compensation, role, winning, coaching, facilities and market size.'}</p><details><summary>Contract rules</summary><p>Cap type: ${leagueRules().salaryCapType}; reference cap: ${money(salaryCap())}; payroll ceiling: ${financeLimitLabel()}. Soft-cap leagues allow Bird-style rights for over-cap re-signings. Each team has a shared MLE pool of 8% of the cap. Minimum contracts pay ${money(leagueRules().minContract)} per year; maximum contracts pay ${money(leagueRules().maxContract)}. All routes respect the spending ceiling and ${rosterMaximum()}-player roster limit. Teams need ${rosterMinimum()} players before the next season.</p><p>Young expiring players drafted by their former team receive restricted status. That team can match an accepted offer sheet. These are simplified game rules, not the NBA CBA. Uncontested unsigned demands fall 7% each round; competing qualifying bids raise demand 4% when no agreement is reached.</p></details></div></section>${faMarketTable(available)}<section class="panel"><div class="panelhead"><h2>Negotiation updates</h2>${f.phase==='market'?'<button onclick="finishFreeAgency()">Finish free agency</button>':''}</div><div class="award-body">${f.log.slice(0,20).map(s=>`<p>${escapeHTML(s)}</p>`).join('')}</div></section></div>`;
}
function readFreeAgency(raw,bad,count,year){if(raw===undefined)return undefined;if(!raw||!Number.isInteger(raw.year)||raw.year>year||!['resign','market','complete'].includes(raw.phase)||!Number.isInteger(raw.round)||raw.round<1||raw.round>10000)bad('invalid free agency');const id=n=>Number.isInteger(n)&&n>=0&&n<=10000000,team=n=>Number.isInteger(n)&&n>=0&&n<count;const offer=o=>{if(!o||!id(o.id)||!team(o.team)||!Number.isFinite(o.salary)||o.salary<0||o.salary>1000||!Number.isInteger(o.years)||o.years<1||o.years>10||!Number.isInteger(o.minutes)||o.minutes<0||o.minutes>40||!['cap','bird','mle','minimum'].includes(o.route)||o.swap!==undefined&&!id(o.swap)||o.upgrade!==undefined&&o.upgrade!==true)bad('invalid contract offer');return {...o}};
 if(!Array.isArray(raw.players)||raw.players.length>3000||!Array.isArray(raw.offers)||raw.offers.length>500||!Array.isArray(raw.pending)||raw.pending.length>30||!Array.isArray(raw.log)||raw.log.length>80||raw.log.some(s=>typeof s!=='string'||s.length>500)||!raw.mle||typeof raw.mle!=='object')bad('invalid free-agent market');const players=raw.players.map(p=>{if(p.departureMood!==undefined&&(!Number.isFinite(p.departureMood)||p.departureMood<0||p.departureMood>100))bad('invalid departing player morale');if(!id(p.id)||p.former!==null&&!team(p.former)||typeof p.rfa!=='boolean'||!Number.isFinite(p.demand)||p.demand<0||p.demand>1000)bad('invalid free agent');return {...p}});if(new Set(players.map(p=>p.id)).size!==players.length)bad('duplicate free agent');const mle={};for(const [key,n] of Object.entries(raw.mle)){if(!team(Number(key))||!Number.isFinite(n)||n<0||n>1000)bad('invalid exception balance');mle[key]=n}return {year:raw.year,phase:raw.phase,round:raw.round,players,offers:raw.offers.map(offer),pending:raw.pending.map(s=>{if(!id(s.id)||!team(s.former)||s.offer?.id!==s.id)bad('invalid offer sheet');return {id:s.id,former:s.former,offer:offer(s.offer)}}),mle,log:[...raw.log]};}

// In-season negotiations share the existing offseason offer dialog when bidding is active.
function negotiateFreeAgent(id){
 if(faBusy||!ownerCanManage())return;
 if(faActive())return faOfferDialog(id);
 const p=state.free.find(p=>p.id===id);if(!p)return toast('Player is no longer available.');
 titleModal('Negotiate with '+escapeHTML(p.name),`<p>${escapeHTML(p.pos)} · Age ${p.age} · ${p.ovr} OVR</p><p>Asking salary: <strong>${money(freeAgentQuote(p))} / year</strong> · Cap room: ${money(Math.max(0,salaryCap()-payroll()))}</p><form onsubmit="submitInSeasonOffer(event,${id})"><div class="tm-grid"><label>Annual salary ($M)<input name="salary" type="number" min="${leagueRules().minContract}" max="${leagueRules().maxContract}" step="${contractMoneyStep()}" value="${freeAgentQuote(p)}" required></label><label>Seasons<select name="years">${contractTerms().map(y=>`<option value="${y}">${y}</option>`).join('')}</select></label></div><p>The current season counts as year one. Accepted offers take effect immediately and follow the league salary cap rules.</p><p id="fa-offer-error" role="alert"></p><button class="primary" ${team().roster.length>=rosterMaximum()?'disabled':''}>Submit offer</button>${team().roster.length>=rosterMaximum()?'<p>Your roster is full. Free a roster spot before signing.</p>':''}</form>`);
}
function inSeasonOfferError(p,salary,years){if(wnbaEnabled())return wnbaInSeasonError(p,salary,years);
 if(faActive())return 'The offseason market has opened. Reopen negotiations to submit a bidding-round offer.';
 if(!p)return 'Player is no longer available.';
 if(!Number.isFinite(salary)||salary<leagueRules().minContract||salary>leagueRules().maxContract||!Number.isInteger(years)||years<leagueRules().minContractYears||years>leagueRules().maxContractYears)return 'Enter a salary and contract length within the league limits.';
 if(team().roster.length>=rosterMaximum())return 'Your roster is full. Release a player first.';
 if(payroll()+salary>financeCapRoomLimit()+.001)return 'Not enough salary-cap room for this offer.';
 if(salary+.001<freeAgentQuote(p))return p.name+' declined. Asking salary is '+money(freeAgentQuote(p))+' per year.';
 return '';
}
async function submitInSeasonOffer(event,id){
 event.preventDefault();if(faBusy||!ownerCanManage())return;
 const values=Object.fromEntries(new FormData(event.target)),salary=Number(values.salary),years=Number(values.years),p=state.free.find(p=>p.id===id),error=inSeasonOfferError(p,salary,years);
 if(error){document.getElementById('fa-offer-error').textContent=error;return}
 const before=snapshotState();faBusy=true;
 try{
  if(wnbaEnabled())wnbaAssign(p,wnbaMakeContract(p,team(),{salary:wnbaDollars(salary),years}));p.salary=salary;p.contractThrough=state.year+years-1;p.tradeWait=15;team().roster.push(p);state.free=state.free.filter(q=>q.id!==id);
  if(typeof dissatisfactionSigned==='function')dissatisfactionSigned(p,team());
  say(team().city+' signs '+p.name+' for '+money(salary)+' per year ('+years+' seasons).');
  addDecision({type:'Signing',description:'Signed '+p.name+' for '+money(salary)+' per year ('+years+' seasons).',players:[{id:p.id,name:p.name}],reasoning:'Negotiated a free-agent contract',immediateOutcome:{capChange:'-'+salary.toFixed(1)+'M'}});
  if(await faSave(before)){closeTitleModal();toast(p.name+' signed');}
 }catch(e){state=before;toast('Could not complete the signing. Please try again.')}finally{faBusy=false;render()}
}

// Full or nearly full CPU rosters still bid on top free agents: one offer per round for a player
// clearly better than the club's weakest. At the roster maximum the offer names that player as a
// swap, released at signing under the usual dead-cap rules (payroll checks already count him).
const FA_UPGRADE_MIN_OVR=75,FA_UPGRADE_MARGIN=5;
function faCPUUpgradeOffers(){const f=state.freeAgency;
 for(const t of state.teams.filter(t=>t.id!==controlledTeamId()||simulationAutopilot())){
  if(t.roster.length<Math.min(rosterMaximum(),Math.max(12,rosterMinimum()))||f.offers.some(o=>o.team===t.id&&o.upgrade))continue;
  const weakest=[...t.roster].sort((a,b)=>a.ovr-b.ovr||tradePlayerValue(a,t)-tradePlayerValue(b,t)||a.id-b.id)[0];if(!weakest)continue;
  const targets=state.free.filter(p=>p.ovr>=Math.max(FA_UPGRADE_MIN_OVR,weakest.ovr+FA_UPGRADE_MARGIN)&&!f.pending.some(s=>s.id===p.id)&&(f.phase==='market'||faEntry(p.id)?.former===t.id)&&!f.offers.some(o=>o.id===p.id&&o.team===t.id)).sort((a,b)=>b.ovr-a.ovr||a.id-b.id);
  for(const p of targets){const e=faEntry(p.id);if(!e)continue;const salary=roundContractAmount(Math.max(faMinimum(p),Math.min(leagueRules().maxContract,e.demand*(hasTrait(p,'mercenary')?1.06:1.02)))),o={id:p.id,team:t.id,salary,years:contractTerm(p.age>31?1:p.age<25?3:2),minutes:32,upgrade:true,...(t.roster.length>=rosterMaximum()?{swap:weakest.id}:{})};o.route=faRoute(p,t,salary);if(faOfferCheck(p,t,o))continue;f.offers.push(o);break}}}
